from dataclasses import dataclass
from enum import Enum

class LengthUnit(Enum):
    METRE = 1.0; KILOMETRE = 1000.0; FOOT = 0.3048

@dataclass(frozen=True)
class Length:
    metres: float
    @classmethod
    def of(cls, amount, unit): return cls(amount * unit.value)
    def __add__(self, other): return Length(self.metres + other.metres)
    def in_unit(self, unit): return self.metres / unit.value
